    @log_input_and_output
    def get_sw_version(self, bts_type='GNB'):
        """
        Gets SW version from active partition read from DU.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'
        :type bts_type: str
        :return: SW version object
        :rtype: SwVersion
        """
        raw_sw_version, _ = self._get_active_and_passive_raw_sw_versions(bts_type=bts_type)
        return SwVersionFactory.create_sw_version(raw_sw_version)

    @log_input_and_output
    def get_active_and_passive_sw_version(self, bts_type='GNB'):
        """
        Gets SW version from active and passive partitions read from DU.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'
        :type bts_type: str
        :return: SW version from active partition, SW version from passive partition, i.e.
                 ('5G19A_FSMK_0006_038451_000299', '5G19A_FSMK_0006_038451_000299T1')
        :rtype: tuple
        """
        return self._get_active_and_passive_raw_sw_versions(bts_type=bts_type)

    @log_input_and_output
    def get_target_sw_version(self, active_sw_version, passive_sw_version):
        """
        Get current SW version and target SW version for next SW update.
        If there will be no passive version (it may happen after YAFT), then active version will be set as passive
        to get correct target sw version.

        :param active_sw_version: SW version from active partition, i.e. 5G19A_FSMK_0006_038451_000299
        :type active_sw_version:  str
        :param passive_sw_version: SW version from passive partition, i.e. 5G19A_FSMK_0006_038451_000299T1
        :type passive_sw_version:  str
        :return: Current SW version and SW version target to next SW upgrade, i.e.
                 ('5G19A_FSMK_0006_038451_000299', 't2_package')
        :rtype: tuple
        """
        active_sw_version = SwVersionFactory.create_sw_version(active_sw_version)

        if not passive_sw_version:
            passive_sw_version = active_sw_version
        else:
            passive_sw_version = SwVersionFactory.create_sw_version(passive_sw_version)

        if active_sw_version.has_t1_suffix or passive_sw_version.has_t1_suffix:
            if active_sw_version.has_t2_suffix or passive_sw_version.has_t2_suffix:
                target_sw_version = 'basic_sw'
            else:
                target_sw_version = 't2_package'
        else:
            target_sw_version = 't1_package'

        return active_sw_version.without_t_suffix.raw, target_sw_version

    @log_input_and_output
    def get_sw_version_with_test_package_variant(self, sw_version, test_package_variant):
        """
        Gets full software version name considering test package variant.
        For example when sw_version="SBTS00_ENB_9999_230607_000014":
           if test_package_variant='t1_package' function returns "SBTS00_ENB_9999_230607_000014T1" as full sw version
           if test_package_variant='t2_package' function returns "SBTS00_ENB_9999_230607_000014T2" as full sw version
           in any other case function returns "SBTS00_ENB_9999_230607_000014" as full sw version.

        :param sw_version: SW version to be downloaded, i.e. 5G19A_FSMK_0006_038451_000299
        :type sw_version: str
        :param test_package_variant: test package type ('basic_sw', 't1_package' or 't2_package')
        :type test_package_variant: str
        :return full software version name with test package suffix i.e. "SBTS00_ENB_9999_230607_000014T1"
        :rtype str

        """
        sw_version = SwVersionFactory.create_sw_version(sw_version)

        if test_package_variant == 't1_package':
            sw_version = sw_version.with_t1_suffix
        elif test_package_variant == 't2_package':
            sw_version = sw_version.with_t2_suffix

        return sw_version

    @log_input_and_output
    def download_software(self, path, sw_version, sw_target='basic_sw'):
        """
        Downloads SW package.

        In T1 or T2 sw_target packages case - T and basic SW packages are being downloaded in parallel processes.
        In basic SW sw_target package case - basic SW package will be downloaded.

        :param path: path where SW package will be saved.
        :type path: str
        :param sw_version: SW version to be downloaded, i.e. 5G19A_FSMK_0006_038451_000299
        :type sw_version: str
        :param sw_target: SW package type ('basic_sw', 't1_package' or 't2_package') to be downloaded.
        :type sw_target: str
        :return full path to downloaded SW package i.e. "/tmp/AirScale-5G20B_10.1800.666T1.zip"
        :rtype str
        """
        sw_version_target = self.get_sw_version_with_test_package_variant(sw_version=sw_version,
                                                                          test_package_variant=sw_target)

        if sw_target == 't1_package' or sw_target == 't2_package':
            return self._download_sw_versions(
                sw_version_target=sw_version_target,
                sw_version_basic=sw_version_target.without_t_suffix,
                path=path,
            )

        return self._download_sw_version(path=path,
                                         sw_version=sw_version_target)

    @log_input_and_output
    @timer()
    def update_software(self, connection, path_to_sw_package, reset_time=20, timeout=900, should_reset_radios=False):
        """
        Performs SW update.

        :param connection: AdminConnection object or if used, string name alias.
        :type connection:  AdminConnection or str
        :param path_to_sw_package: path to SW package which will be used during update
        :type path_to_sw_package: str
        :param reset_time: time to reset site after update
        :type reset_time:  int
        :param timeout: time to wait for positive update result
        :type timeout:  int
        :param should_reset_radios: whether to reset radios after software update, defaults to False
        :type should_reset_radios: bool
        """
        self.admin.update_software(sw_package=path_to_sw_package, connection=connection, timeout=int(timeout),
                                   should_reset_radios=should_reset_radios)
        time.sleep(int(reset_time))

    @log_input_and_output
    def upload_same_sw_version(self, connection, timeout=1800, download_path='/home/ute'):
        """
        Reads current SW version number from BTS and re-uploads same version after downloading it.
        If required SW package is already present on local machine in /home/ute dir then it will be used.

        :param connection: alias of connection to BTS i.e. 'admin'
        :type connection: str
        :param timeout: timeout for complete software update (download + activation); 1800 on default
        :type timeout: int
        :param download_path: path to which downloaded SW version will be saved; defaults to '/home/ute'
        :type download_path: str
        """
        log_operation('Uploading same SW version')

        current_sw_version = SwVersionFactory.create_sw_version(self._get_sw_version(connection))

        log_step('Checking whether SW package already exists locally...')
        sw_package_path = self._check_if_sw_package_is_downloaded_already_and_get_filepath(sw_version=current_sw_version)
        if not sw_package_path:
            log_step('SW package not found locally, downloading...')
            sw_package_path = self._download_sw_version(download_path, current_sw_version)
        else:
            log_step(f'SW package {current_sw_version.package} found locally at {sw_package_path}')

        self.update_software(connection, sw_package_path, timeout=timeout)
        time.sleep(60)
        log_result('Same SW version uploaded successfully')

    @log_input_and_output
    def rollback_software(self, connection, bts_type='GNB', timeout=900):
        """
        Perform software rollback - software version from passive partition will be activated.

        :param connection: alias of connection to BTS i.e. 'admin'
        :type connection: str
        :param bts_type: type of bts, can be 'GNB' or 'ENB'
        :type bts_type: str
        :param timeout: timeout for complete software rollback; defaults to 900 seconds
        :type timeout: int
        """
        active_sw, passive_sw = self._get_active_and_passive_raw_sw_versions(bts_type=bts_type)

        log_operation('Performing software rollback from {} to {}'.format(active_sw, passive_sw))
        self.admin.rollback_software(timeout=timeout, connection=connection)

        time.sleep(60)
        log_result('Software rollback performed successfully.')

    @log_input_and_output
    def send_sw_package_to_smod(self, package_name, local_path, smod_path='/ram', bts_type='GNB'):
        """
        Sends sw package from VMs local path to BTS SMOD using SCP protocol.

        :param package_name: full name (with extension) of sw package to send, e.g. "factory_sw_aeqn.tar"
        :type package_name: str
        :param local_path: absolute local path to directory with particular sw package, e.g. "/tmp"
        :type local_path: str
        :param smod_path: absolute smod remote path to directory where sw package will be sent,
                          default parameter value is "/ram"
        :type smod_path: str
        :param bts_type: type of bts, can be 'GNB' or 'ENB'
        :type bts_type: str
        """
        try:
            credentials = get_ssh_connection_credentials(bts_type=bts_type)
            self.smod.connect_to(credentials['host'], credentials['username'], credentials['password'])
            self.smod.upload_file(local_path=f'{local_path}/{package_name}',
                                  remote_path=f'{smod_path}/{package_name}')
            log_result(f"Uploading file {package_name} from local path {local_path}/ to smod path {smod_path}/ "
                       f"finished successfully.")
        finally:
            self.smod.close_connection()

    @log_input_and_output
    def send_sw_package_from_smod_to_ru(self, rmod_ip, username, password,
                                        package_name, smod_path='/ram', rmod_path='/ram', slave_bts=False):
        """
        Sends file from BTS SMOD to RU via FHNET container, using SCP protocol.

        :param rmod_ip: ip address of the radio unit which the file will be sent
        :type rmod_ip: str
        :param username: username of the radio unit which the file will be sent
        :type username: str
        :param password: password to the radio unit which the file will be sent
        :type password: str
        :param package_name: full name (with extension) of sw package to send, e.g. "factory_sw_aeqn.tar"
        :type package_name: str
        :param smod_path: absolute smod remote path to directory with sent sw package, default parameter value is "/ram"
        :type smod_path: str
        :param rmod_path: absolute rmod remote path to directory where sw package will be sent,
                          default parameter value is "/ram"
        :type rmod_path: str
        :param slave_bts: Used for fullrack configuration only. True if RMOD's connection should be performed
                          on slave bts, False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        """
        smod_invoke_session = InvokeSshHandler()
        smod_invoke_session.send_file_from_smod_to_rmod(package_name, smod_path, rmod_path, rmod_ip, username, password,
                                                        slave_bts)

    @log_input_and_output
    def install_rfsw_using_swman_shell(self, rmod_ip, username, password,
                                       rfsw_package_name, rfsw_package_path, rfsw_version, rfsw_checksum=None,
                                       timeout=1800, repetition_interval=30, slave_bts=False):
        """
        Installs RFSW package on RU version via FHNET, using SWman command.

        :param rmod_ip: ip address of the radio unit to install rfsw
        :type rmod_ip: str
        :param username: username of the radio unit to install rfsw
        :type username: str
        :param password: password to the radio unit to install rfsw
        :type password: str
        :param rfsw_package_name: full name (with extension) of sw package to install, e.g. "factory_sw_aeqn.tar"
        :type rfsw_package_name: str
        :param rfsw_package_path: absolute rmod path to directory with rfsw package, e.g. "/ram"
        :type rfsw_package_path: str
        :param rfsw_version: name of rfsw version to installation. Name can be anything and will be required during
                             software activation, e.g "aeqn_package_001"
        :type rfsw_version: str
        :param rfsw_checksum: checksum of rfsw package to installation, e.g "0x39F05653". Default set on None,
                              means that script will try to get checksum from rfsw package name.
        :type rfsw_checksum: str
        :param timeout: timeout (in seconds) for software installation, 1800 on default
        :type timeout: int
        :param repetition_interval: interval time (in seconds) for refreshing shell console during software installing,
                                    30 on default
        :type repetition_interval: int
        :return: version of installed rfsw package, e.g. "aeqn_package_001"
        :rtype: string
        :param slave_bts: Used for fullrack configuration only. True if RMOD's connection should be performed
                          on slave bts, False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        :raises SwVersionsDoNotMatch: when software installation failed
        """
        if rfsw_checksum is None:
            rfsw_checksum = self._prepare_rfsw_checksum(rfsw_package_name)

        sudo_mode = "sudo " if username == "serviceuser" else ""
        command = f'{sudo_mode}SWmanShellCommand -s {rfsw_package_path}/{rfsw_package_name} {rfsw_checksum} "{rfsw_checksum}" \
                  "{rfsw_checksum}"'

        smod_invoke_session = InvokeSshHandler()
        smod_invoke_session.connect_to_rmod(ip=rmod_ip, username=username, password=password, slave_bts=slave_bts)
        log_to_console("Installing RFSW ...")

        try:
            smod_invoke_session.send_command_and_return_output(command,
                                                               expected_phrase="status:        OK",
                                                               unacceptable_phrase="status:        fail",
                                                               timeout=timeout,
                                                               repetition_interval=repetition_interval,
                                                               refresh_session=True,
                                                               slave_bts=slave_bts)
        except ExpectedPhraseNotFoundError:
            rfsw_check = self._handle_exception_expected_phrase_error_during_rfsw_istallation(rfsw_package_name,
                                                                                              rmod_ip,
                                                                                              username,
                                                                                              password,
                                                                                              slave_bts)
            if rfsw_check is False:
                raise SwVersionsDoNotMatch(f'RFSW package {rfsw_package_name} probably has not been installed. '
                                           f'Please check RFSW software manually')

        log_to_console("RFSW installation completed successfully")
        return rfsw_version

    @log_input_and_output
    def activate_rfsw_using_swman_shell(self, rmod_ip, username, password,
                                        rfsw_package_name, rfsw_checksum=None, slave_bts=False):
        """
        Activates RFSW package on RU version via FHNET, using SWman command. RFSW package must be installed first
        and available on passive partition before activation.

        :param rmod_ip: ip address of the radio unit to activate rfsw
        :type rmod_ip: str
        :param username: username of the radio unit to activate rfsw
        :type username: str
        :param password: password to the radio unit to activate rfsw
        :type password: str
        :param rfsw_package_name: full name (with extension) of sw package to activate, e.g. "factory_sw_aeqn.tar"
        :type rfsw_package_name: str
        :param rfsw_checksum: checksum of rfsw package to installation, e.g "0x39F05653". Default set on None,
                              means that script will try to get checksum from rfsw package name.
        :type rfsw_checksum: str
        :param slave_bts: Used for fullrack configuration only. True if RMOD's connection should be performed
                          on slave bts, False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        """
        if rfsw_checksum is None:
            rfsw_checksum = self._prepare_rfsw_checksum(rfsw_package_name)

        sudo_mode = "sudo " if username == "serviceuser" else ""
        command = f'{sudo_mode}SWmanShellCommand -a "{rfsw_package_name}" "{rfsw_package_name}" "{rfsw_package_name}" {rfsw_checksum}'

        smod_invoke_session = InvokeSshHandler()
        smod_invoke_session.connect_to_rmod(ip=rmod_ip, username=username, password=password, slave_bts=slave_bts)

        log_to_console("Activating RFSW ...")
        smod_invoke_session.send_command_and_return_output(command,
                                                           expected_phrase="status:        OK",
                                                           unacceptable_phrase="status:        fail",
                                                           timeout=120,
                                                           repetition_interval=2,
                                                           slave_bts=slave_bts)
        log_to_console("RFSW activation completed successfully")

    @staticmethod
    @log_input_and_output
    def get_current_running_build_name_from_swmancommand_output(swmancommand_output):
        """
        Gets current running build name (RFSW) based on RMOD's "SWmanShellCommand -i" command output.

        :param swmancommand_output: output of "SWmanShellCommand -i" command executed on RMOD
        :type swmancommand_output: str
        :return: current running build name from given SWmanShellCommand output
        :rtype: str
        :raises InvalidSwVersion when 'runningBuildName' not found in SWmanShellCommand output.
        """
        for line in swmancommand_output.split("\n"):
            if "runningBuildName:" in line:
                return line.split("runningBuildName:")[1].lstrip()

        raise InvalidSwVersion(f"'runningBuildName' not found in SWmanShellCommand command output: "
                               f"{swmancommand_output}")

