    @log_input_and_output
    def is_knife_build(self, sw_version: Union[SwVersion, str]) -> bool:
        """
        Checks if given SW version is knife build.

        :param sw_version: SW version which should be checked
        :type sw_version: str or SwVersion
        :return: True if given SW version is knife build, False otherwise
        :rtype: bool
        """
        if isinstance(sw_version, str):
            sw_version = SwVersionFactory.create_sw_version(sw_version)

        return isinstance(sw_version, SbtsKnifeSwVersion)

    @log_input_and_output
    def _get_active_and_passive_raw_sw_versions(self, bts_type='GNB'):
        """
        Gets SW version from active and passive partitions read from DU.
        :param bts_type: type of bts, can be 'GNB' or 'ENB'
        :type bts_type: str
        :return: SW version from active partition, SW version from passive partition, i.e.
                 ('5G19A_FSMK_0006_038451_000299', '5G19A_FSMK_0006_038451_000299T1')
        :rtype: tuple
        """
        try:
            credentials = get_ssh_connection_credentials(bts_type=bts_type)
            self.smod.connect_to(credentials['host'], credentials['username'], credentials['password'])

            active = self.smod.execute(command='ls /ffs/run | grep TargetBD_SBTS').split('\r\n')
            passive = self.smod.execute(command='ls /ffs/stb | grep TargetBD_SBTS').split('\r\n')

            active_sw_version = active[0].lstrip('TargetBD_').rstrip('.xml')
            passive_sw_version = passive[0].lstrip('TargetBD_').rstrip('.xml')
        finally:
            self.smod.close_connection()

        return active_sw_version, passive_sw_version

    @log_input_and_output
    def _get_sw_version(self, connection):
        """
        Gets SW version read from admin.

        :param connection: AdminConnection object or if used, string name alias.
        :type connection:  AdminConnection or str
        :return: SW version, i.e. '5G19A_FSMK_0006_038451_000299'
        :rtype: str
        """
        return self.admin.get_sw_version(connection=connection)

    @log_input_and_output
    def _download_sw_versions(self, sw_version_target, sw_version_basic, path):
        sw_versions = (sw_version_target, sw_version_basic)

        for sw_version in sw_versions:
            log_step('Downloading: {} SW package ...'.format(sw_version.raw))
            self._download_sw_version(path=path, sw_version=sw_version)
            sw_file_path = os.path.join(path, sw_version.package)

            self._validate_downloaded_packages(sw_file_path)

        log_result("SW packages has been downloaded successfully")

        return os.path.join(path, sw_version_target.package)

    @log_input_and_output
    def _download_sw_version(self, path, sw_version):
        """
        Downloads SW package from remote repository and stores it under the path.
        If SW package with given name already exists in path then it will not be downloaded.
        If not enough free disk space will be detected then there will be an attempt to free some additional space.
        If not able to free enough disk space then error will be raised.
        Attempt to free some disk space is done only for 5G SW version.

        :param path: directory to which SW package should be downloaded, i.e. '/tmp'
        :type path: str
        :param sw_version: SW version which should be downloaded
        :type sw_version: SwVersion
        :raises NotEnoughSpace: if not able to free enough disk space
        """
        package_path = os.path.join(path, sw_version.package)

        if sw_version.package not in os.listdir(path):
            self._ensure_free_space_on_local_drive(path, sw_version)

            for attempt in range(5):
                log_step("Getting SW package ...")
                headers = {"X-JFrog-Art-Api": self._artifactory_token} \
                    if not isinstance(sw_version, SbtsKnifeSwVersion) else {}

                with requests.get(url=sw_version.url, stream=True, timeout=20, headers=headers) as response:
                    if response.status_code == 200:
                        with open(package_path, 'wb') as sw_package:
                            for chunk in response.iter_content(chunk_size=10000):
                                sw_package.write(chunk)
                    else:
                        log_env_state(
                            f'SW package download procedure failed with code: {response.status_code} - '
                            f'{response.reason}, retrying in 60 seconds ...'
                        )
                        time.sleep(60)
                        continue

                if sw_version.package in os.listdir(path):
                    if sw_version.checksum:
                        log_operation("Validating SW package checksum")
                        if not self._validate_sw_package_checksum(sw_version=sw_version,
                                                                  local_path_to_package=path):
                            raise IncorrectPackageChecksum(
                                "Actual checksum of software files does not match expected checksum"
                                ", package might be corrupted")
                        log_result("SW package checksum validation completed successfully")
                    break

            else:
                raise DownloadProcedureError(
                    f'Could not download SW package with error: "{response.status_code} - {response.reason}"'
                )

        else:
            log_env_state('SW package already present in given path, no need to download it again')

        return package_path

    @log_input_and_output
    def _download_external_package_for_sw_version(self, path, sw_version, package_name):
        """
        Downloads external package for particular SW version from remote repository and stores it under the path.

        :param path: directory to which external package should be downloaded, i.e. '/tmp'
        :type path: str
        :param sw_version: SW version for external package, i.e.: 'SBTS00_ENB_9999_240806_000003'
        :type sw_version: SwVersion
        :param package_name: name of external package, i.e. 'SBTS00_ENB_9999_240806_000003_tti-dec.deb'
        :type package_name: str

        :raises DownloadProcedureError: if external SW package download has failed
        """
        external_package_path = os.path.join(path, package_name)

        if package_name not in os.listdir(path):
            for attempt in range(5):
                log_step("Getting external SW package...")
                with requests.get(url=f"{sw_version.packages_url}{package_name}", stream=True, timeout=20,
                                  headers={"X-JFrog-Art-Api": self._artifactory_token}) as response:
                    if response.status_code == 200:
                        with open(external_package_path, 'wb') as sw_package:
                            for chunk in response.iter_content(chunk_size=10000):
                                sw_package.write(chunk)
                    else:
                        log_env_state(
                            f'External SW package download procedure failed with code: {response.status_code} - '
                            f'{response.reason}, retrying in 60 seconds...'
                        )
                        time.sleep(60)
                        continue

                if package_name in os.listdir(path):
                    break

            else:
                raise DownloadProcedureError(
                    f"Could not download external SW package with error: '{response.status_code} - {response.reason}'"
                )

        else:
            log_env_state('External SW package already present in given path, no need to download it again.')

        return external_package_path

    @log_input_and_output
    def _ensure_free_space_on_local_drive(self, path, sw_version):
        """
        Ensures that local machine drive will have enough space to download given SW package.
        If not able to free enough space then error will be raised.
        Supports only 5G SW version.

        :param path: path which should be cleaned up.
        :type path: str
        :param sw_version: SW version which should fit on local drive
        :type sw_version: SwVersion
        :raises NotEnoughSpace: when removing old SW packages was not enough to clean up local drive appropriately.
        """
        if not vm.check_whether_vm_has_free_space(path, sw_version.size):
            for file_ in os.listdir(path):
                if 'AirScale' in file_:
                    os.system('rm {}/{}'.format(path, file_))
                    log_result("Remove {} from {}".format(file_, path))

            if not vm.check_whether_vm_has_free_space(path, sw_version.size):
                raise NotEnoughSpace('No space left on device')

    @log_input_and_output
    def _validate_sw_package_checksum(self, sw_version, local_path_to_package):
        """
        Validates checksum of software package based on expected value from md5 file and actual calculated value.

        :param sw_version: SW version which checksum will be validated
        :type sw_version: SwVersion
        :param local_path_to_package: local path to downloaded software package
        :type local_path_to_package: str
        :return: True whether checksum of SW package is correct, otherwise False.
        :rtype: bool
        """
        actual_checksum = self._get_file_checksum(os.path.join(local_path_to_package, sw_version.url.split('/')[-1]))

        return str(sw_version.checksum) == str(actual_checksum)

    @staticmethod
    @log_input_and_output
    def _get_file_checksum(file_path):
        """
        Gets checksum of file provided.

        :param file_path: local path to file that checksum will be checked
        :type file_path: str
        :return: provided file checksum
        :rtype: str
        """
        hash_md5 = hashlib.md5()

        with open(file_path, "rb") as file:
            for chunk in iter(lambda: file.read(4096), b""):
                hash_md5.update(chunk)

        return hash_md5.hexdigest()

    @staticmethod
    @log_input_and_output
    def _validate_downloaded_packages(sw_file_path):
        """
        Checks if file was downloaded correctly.

        :param sw_file_path: local path to the downloaded sw build
        :type sw_file_path: str
        :raises DownloadProcedureError: when file is either empty or missing.
        """
        if not os.path.isfile(sw_file_path):
            raise DownloadProcedureError(
                "File was not found in specified path: {}".format(sw_file_path)
            )

        elif os.path.getsize(sw_file_path) == 0:
            raise DownloadProcedureError(
                "Downloaded file is empty: {}".format(sw_file_path)
            )

    @log_input_and_output
    def _prepare_rfsw_checksum(self, rfsw_package_name):
        """
        Returns rfsw checksum included in package name.
        :param rfsw_package_name: name of rfsw package, e.g. "rfsw-package-erm6_0x39F05653.tar"
        :type rfsw_package_name: str
        :return: checksum of rfsw package in eight characters format., e.g. "0x39F05653"
        :rtype: str
        :raises IncorrectPackageChecksum: when returned checksum has incorrect format
        """
        checksum = rfsw_package_name.split("0x")[-1].rsplit(".tar")[0]
        if len(checksum) == 8:
            return f"0x{checksum}"
        raise IncorrectPackageChecksum(
            f"Actual checksum of rfsw package does not match expected checksum, "
            f"package {rfsw_package_name} might be corrupted")

    @log_input_and_output
    def _handle_exception_expected_phrase_error_during_rfsw_istallation(self, rfsw_package_name, rmod_ip, username,
                                                                        password, slave_bts):
        """
        Method performs check of installed rfsw packages. Used command is "sudo SWmanShellCommand -i".
        Command output should contain rfsw packages versions installed on active and pasive RU partitions.
        :param rfsw_package_name: name of rfsw package which should be installed,
                                  e.g."rfsw-package-erm6_0x39F05653.tar"
        :type rfsw_package_name: str
        :param rmod_ip: ip address of the radio unit to check rfsw package
        :type rmod_ip: str
        :param username: username of the radio unit to check rfsw package
        :type username: str
        :param password: password to the radio unit to check rfsw package
        :type password: str
        :param slave_bts: True if RMOD's connection should be performed on slave bts,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool
        :return: True if package with given rfsw_package_name is installed, False otherwise.
        :rtype: bool
        """
        smod_invoke_session = InvokeSshHandler()
        smod_invoke_session.connect_to_rmod(ip=rmod_ip, username=username, password=password, slave_bts=slave_bts)
        rfsw_versions = smod_invoke_session.send_command_and_return_output("sudo SWmanShellCommand -i", timeout=10,
                                                                           slave_bts=slave_bts)
        return rfsw_package_name in rfsw_versions

    @log_input_and_output
    def _check_if_sw_package_is_downloaded_already_and_get_filepath(self, sw_version: Union[SwVersion, str]) \
            -> Union[str, None]:
        """
        Checks if SW package with given name is already downloaded to local path and returns its full path.

        :param sw_version: SW version which should be checked
        :type sw_version: SwVersion or str
        :return: full path to SW package if it exists, None otherwise
        :rtype: str or None
        """
        if isinstance(sw_version, str):
            sw_version = SwVersionFactory.create_sw_version(sw_version)
        return vm.find_file_and_get_filepath(filename=sw_version.package)
